<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateUidVO;

trait TemplateUidAttributeHolder
{
  protected TemplateUidVO|string|null $uid = null;
  protected bool $uidAssigned = false;

  public function getUidOrDefault(TemplateUidVO $uid): TemplateUidVO
  {
  if( $this->uidAssigned ) {
    \assert( null !== $this->uid );
    return TemplateUidVO::from($this->uid);
  } else {
    return $uid;
  }
  }
  public function uid(TemplateUidVO|string|null $uid): static
  {
    $this->uid = $uid;
    $this->uidAssigned = true;
    return $this;
  }
  public function getUid(): ?string
  {
    return $this->uid instanceof TemplateUidVO ? $this->uid->value() : $this->uid;
  }
  public function isUidAssigned(): bool
  {
    return $this->uidAssigned;
  }
  public function writeUidTo(mixed $att): void
  {
    if ($this->uidAssigned) {
      \assert(null !== $this->uid);
      $att->uid($this->uid);
    }  }
  public function readUidFrom(mixed $att): void
  {
    if ($att->isUidAssigned() ) {
      $uid = $att->getUid();
      \assert(null !== $uid);
      $this->uid($uid);
    }
  }
  public function unsetUid(): static
  {
    $this->uidAssigned = false;
    return $this;
  }
  protected function withDefaultUid(): void   
  {
  }
  protected function withAssertedUidRules(self $value, ConstraintFailList $errorsList): void  
  {
    if ($value->uidAssigned = $this->uidAssigned) {
      $value->uid = TemplateUidVO::tryFrom($this->uid, $errorsList);
    }
  }
}
